SELECT id, game_id, club_id, court_id, s3_object_key
         FROM public.cctv_recordings
         WHERE status = 'RECORDING' AND stop_deadline <= CURRENT_TIMESTAMP;

UPDATE public.cctv_recordings
           SET status = 'COMPLETED', actual_stop_time = CURRENT_TIMESTAMP
           WHERE id = $1;

INSERT INTO public.game_videos (game_id, club_id, court_id, cctv_id, title, video_url, status)
           VALUES ($1, $2, $3, $4, $5, $6, 'AVAILABLE')
           ON CONFLICT DO NOTHING;

INSERT INTO public.wallet_transactions (
               wallet_id, user_id, type, amount, status, description
             ) VALUES (
               (SELECT id FROM public.wallets WHERE user_id = $1),
               $1, 'REFUND', $2, 'SUCCESS',
               $3
             );

UPDATE public.game_players
             SET payment_status = 'REFUNDED', updated_at = CURRENT_TIMESTAMP
             WHERE game_id = $1 AND user_id = $2;

UPDATE public.games
         SET status = 'ONGOING', updated_at = CURRENT_TIMESTAMP
         WHERE id = $1;

UPDATE public.games
         SET status = 'COMPLETED', updated_at = CURRENT_TIMESTAMP
         WHERE id = $1;

SELECT COALESCE(SUM(amount_paid), 0) as total_revenue
      FROM public.court_bookings
      WHERE status IN ('CONFIRMED', 'COMPLETED', 'PAID');

SELECT COALESCE(SUM(amount), 0) as total_refunds
      FROM public.transactions
      WHERE type ILIKE '%REFUND%';

SELECT COALESCE(SUM(amount), 0) as total_refunds
        FROM public.wallet_transactions
        WHERE description ILIKE '%REFUND%';

INSERT INTO public.user_device_tokens (user_id, device_token, device_type, is_active)
           SELECT $1, $2, $3, true
           WHERE NOT EXISTS (
             SELECT 1 FROM public.user_device_tokens WHERE user_id = $1 AND device_token = $2
           );

UPDATE public.court_bookings
       SET status = 'CANCELLED', cancellation_reason = $1
       WHERE id = $2 RETURNING *;

UPDATE public.cctv_cameras
      SET ${fields.join(", ")}
      WHERE id = $${idx}
      RETURNING *;

UPDATE public.cctv_recordings
       SET status = $1, recording_status = $1, actual_stop_time = COALESCE($2, CURRENT_TIMESTAMP), actual_stopped_at = COALESCE($2, CURRENT_TIMESTAMP)
       WHERE id = $3 RETURNING *;

UPDATE public.cctv_recordings
       SET stop_deadline = $1, post_match_stop_at = $1
       WHERE id = $2 RETURNING *;

SELECT id, start_time, end_time, status
       FROM public.court_bookings
       WHERE court_id = $1 AND booking_date = $2 AND status = 'CONFIRMED';

SELECT * FROM public.game_activity_logs
      WHERE game_id = $1
      ORDER BY created_at ASC;

INSERT INTO public.payment_orders (
         id, user_id, provider, provider_order_id, idempotency_key,
         amount_paise, currency, purpose, status, metadata, expires_at
       ) VALUES ($1, $2, 'RAZORPAY', $3, $4, $5, 'INR', $6, 'PENDING', $7, CURRENT_TIMESTAMP + INTERVAL '30 minutes')
       ON CONFLICT (id) DO UPDATE 
       SET provider_order_id = EXCLUDED.provider_order_id, updated_at = CURRENT_TIMESTAMP;

